const payload = 'x'.repeat(9441);

function delay(milliseconds) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/sync') {
      return new Response(payload, {
        status: 200,
        headers: { 'content-type': 'application/octet-stream' },
      });
    }
    if (url.pathname === '/drain') {
      // Deliberately slow (well under the demo's drain timeout): guarantees
      // requests sent just before SIGTERM are still in flight when the
      // signal arrives, so the orchestrator-contract benchmark can prove
      // they drain successfully instead of racing an instant response.
      await delay(400);
      return new Response(payload, {
        status: 200,
        headers: { 'content-type': 'application/octet-stream' },
      });
    }
    return new Response('not found', { status: 404 });
  },
};
